		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
			return fmt.Errorf("%w: %s", ErrRefNotFound, refName)
		}
		return fmt.Errorf("failed to check ref %s: %w", refName, err)

